import{_ as e,o as a,c as d,a4 as n}from"./chunks/framework.vNSRaLQv.js";const u=JSON.parse('{"title":"Windows 终端注入技术攻坚","description":"","frontmatter":{"title":"Windows 终端注入技术攻坚","date":"2026-05-28T00:00:00.000Z"},"headers":[],"relativePath":"posts/Windows终端注入技术攻坚.md","filePath":"posts/Windows终端注入技术攻坚.md"}'),s={name:"posts/Windows终端注入技术攻坚.md"};function o(i,t,r,l,h,p){return a(),d("div",null,[...t[0]||(t[0]=[n(`<h1 id="windows-终端注入技术攻坚" tabindex="-1">Windows 终端注入技术攻坚 <a class="header-anchor" href="#windows-终端注入技术攻坚" aria-label="Permalink to &quot;Windows 终端注入技术攻坚&quot;">​</a></h1><blockquote><p>把命令塞进 Claude Code / Codex CLI 窗口的那些事 2026-05-28 ~ 2026-05-30</p></blockquote><hr><h2 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to &quot;背景&quot;">​</a></h2><p>在多 Agent 对证循环中，路由层需要把指令注入到 CC / Codex 的终端窗口。 这个问题在 Windows 上比 Linux 难得多——没有 tmux，没有 PTY 复用，没有 send-keys。</p><h2 id="第一阶段-setforegroundwindow-keybd-event" tabindex="-1">第一阶段：SetForegroundWindow + keybd_event <a class="header-anchor" href="#第一阶段-setforegroundwindow-keybd-event" aria-label="Permalink to &quot;第一阶段：SetForegroundWindow + keybd_event&quot;">​</a></h2><h3 id="方案" tabindex="-1">方案 <a class="header-anchor" href="#方案" aria-label="Permalink to &quot;方案&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>window-server.py（端口 8765）</span></span>
<span class="line"><span>  → inject-fast.ps1</span></span>
<span class="line"><span>    → ShowWindow(SW_SHOW)</span></span>
<span class="line"><span>    → SetForegroundWindow</span></span>
<span class="line"><span>    → 剪贴板写入文本</span></span>
<span class="line"><span>    → keybd_event(Ctrl+V)</span></span>
<span class="line"><span>    → keybd_event(Enter)</span></span>
<span class="line"><span>    → SetForegroundWindow(恢复前台)</span></span></code></pre></div><h3 id="成果" tabindex="-1">成果 <a class="header-anchor" href="#成果" aria-label="Permalink to &quot;成果&quot;">​</a></h3><ul><li>注入速度 ~200ms</li><li>HWND 查找用 <code>find-window.ps1</code></li><li>用户验证：<strong>&quot;非常稳&quot;</strong></li><li>文件：<code>inject-fast.ps1</code>、<code>window-server.py</code>、<code>find-window.ps1</code></li></ul><h3 id="缺点" tabindex="-1">缺点 <a class="header-anchor" href="#缺点" aria-label="Permalink to &quot;缺点&quot;">​</a></h3><ul><li>窗口必须在前台才能接收按键</li><li>用户工作时窗口闪烁抢焦点</li><li>需要 HWND 跟踪，窗口重建后 HWND 变化</li></ul><hr><h2 id="第二阶段-conpty-stdin-方案-失败" tabindex="-1">第二阶段：ConPTY / stdin 方案（失败） <a class="header-anchor" href="#第二阶段-conpty-stdin-方案-失败" aria-label="Permalink to &quot;第二阶段：ConPTY / stdin 方案（失败）&quot;">​</a></h2><p>试图通过 ConPTY API 绕过窗口层：</p><table tabindex="0"><thead><tr><th>方案</th><th>结果</th><th>原因</th></tr></thead><tbody><tr><td><code>conpty-server.py</code></td><td>❌</td><td>CC 检测到无终端后立即退出</td></tr><tr><td>直接 stdin 写</td><td>❌</td><td><code>[Errno 22] Invalid argument</code></td></tr><tr><td>CC <code>--print</code> 模式</td><td>❌</td><td>一次性进程，不是持久会话</td></tr></tbody></table><p>结论：<strong>CC 和 Codex 都是用 prompt_toolkit 的交互式 REPL，不支持 stdin 管道交互。</strong></p><hr><h2 id="第三阶段-windows-自动化框架评估" tabindex="-1">第三阶段：Windows 自动化框架评估 <a class="header-anchor" href="#第三阶段-windows-自动化框架评估" aria-label="Permalink to &quot;第三阶段：Windows 自动化框架评估&quot;">​</a></h2><table tabindex="0"><thead><tr><th>框架</th><th>结果</th><th>原因</th></tr></thead><tbody><tr><td>pywinauto</td><td>❌</td><td>同 keybd_event 限制</td></tr><tr><td>AutoHotkey</td><td>❌</td><td>同样受 ReadConsoleInputW 限制</td></tr><tr><td>AutoIt</td><td>❌</td><td>同样</td></tr><tr><td>WinAppDriver</td><td>❌</td><td>面向 UWP/Web 应用，非 Console</td></tr></tbody></table><p>根因：<strong>Windows Terminal / ConHost 的输入通过 <code>ReadConsoleInputW</code> 直接从内核态读取，绕过窗口消息队列。</strong> 所有用户态注入框架都无法绕过。</p><hr><h2 id="第四阶段-切换到-wsl-tmux-彻底解决" tabindex="-1">第四阶段：切换到 WSL + tmux（彻底解决） <a class="header-anchor" href="#第四阶段-切换到-wsl-tmux-彻底解决" aria-label="Permalink to &quot;第四阶段：切换到 WSL + tmux（彻底解决）&quot;">​</a></h2><p>放弃直接在 Windows 上注入，改用 <strong>WSL + tmux</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>n8n（Windows 路由层）</span></span>
<span class="line"><span>  → wsl -e tmux send-keys -t cc &quot;/develop-ws&quot; Enter</span></span>
<span class="line"><span>  → CC 在 WSL 中通过 tmux session 运行</span></span></code></pre></div><h3 id="优点" tabindex="-1">优点 <a class="header-anchor" href="#优点" aria-label="Permalink to &quot;优点&quot;">​</a></h3><ul><li>✅ tmux 原生支持 <code>send-keys</code>，零延迟</li><li>✅ 窗口不需要前台，后台注入</li><li>✅ session name 即身份（cc / codex / ws001）</li><li>✅ 多工作间天然隔离</li><li>✅ 不怕窗口焦点抢夺</li></ul><h3 id="代价" tabindex="-1">代价 <a class="header-anchor" href="#代价" aria-label="Permalink to &quot;代价&quot;">​</a></h3><ul><li>CC / Codex 必须在 WSL 环境中运行（Linux 环境）</li><li>文件系统通过 <code>/mnt/c/...</code> 访问 Windows 文件</li><li>需要一个 WSL 发行版</li></ul><hr><h2 id="技术演进总表" tabindex="-1">技术演进总表 <a class="header-anchor" href="#技术演进总表" aria-label="Permalink to &quot;技术演进总表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>时间</th><th>方案</th><th>状态</th><th>核心文件</th></tr></thead><tbody><tr><td>5/28</td><td>SetForegroundWindow + keybd_event</td><td>✅ 验证通过</td><td>inject-fast.ps1, window-server.py</td></tr><tr><td>5/29</td><td>ConPTY 管道</td><td>❌ 阻塞</td><td>conpty-server.py</td></tr><tr><td>5/29</td><td>CC --print 模式</td><td>❌ 一次性</td><td>cc-server.py</td></tr><tr><td>5/29</td><td>自动化框架（pywinauto/AHK）</td><td>❌ 不可行</td><td>—</td></tr><tr><td>5/30</td><td>WSL + tmux send-keys</td><td>✅ 最终方案</td><td>README.md</td></tr></tbody></table><hr><h2 id="经验教训" tabindex="-1">经验教训 <a class="header-anchor" href="#经验教训" aria-label="Permalink to &quot;经验教训&quot;">​</a></h2><ol><li><strong>不要跟 Windows Console 子系统硬刚</strong> — ReadConsoleInputW 是内核态操作，用户态无解</li><li><strong>平台能力有本质差异</strong> — Windows 的窗口模型不适合 Agent 自动化，WSL 是桥梁</li><li><strong>HWND 不是稳定的标识符</strong> — 窗口重建后 HWND 变化，tmux session name 是更好的方案</li><li><strong>先验证最天然的方式</strong> — tmux send-keys 早就在 Linux 上解决了这个问题</li></ol>`,35)])])}const b=e(s,[["render",o]]);export{u as __pageData,b as default};
